// High-Definition Realistic Medical Human Face Articulation Images for All Sounds

const MOUTH_IMAGES = {
  bilabial: "data:image/png;base64,",
  labiodental: "data:image/png;base64,",
  alveolar: "data:image/png;base64,",
  velar: "data:image/png;base64,",
  palatal: "data:image/png;base64,",
  dental: "data:image/png;base64,",
  retroflex: "data:image/png;base64,"
};

export function getMouthDiagramSVG(char, sectionType) {
  const c = char ? char.toLowerCase() : '';
  const s = sectionType ? sectionType.toLowerCase() : '';

  let imgKey = 'bilabial';
  let title = 'Mô Phỏng Khẩu Hình Giải Phẫu Mặt Người Chuẩn';

  // 1. THANH MẪU (Consonants)
  if (['b', 'p', 'm'].includes(c)) {
    imgKey = 'bilabial';
    title = 'Âm hai môi (' + c + '): Hai môi khép dính dẹp';
  } else if (c === 'f') {
    imgKey = 'labiodental';
    title = 'Âm răng môi (f): Răng trên chạm môi dưới';
  } else if (['d', 't', 'n', 'l'].includes(c)) {
    imgKey = 'alveolar';
    title = 'Âm đầu lưỡi giữa (' + c + '): Đầu lưỡi chạm chân răng trên';
  } else if (['g', 'k', 'h'].includes(c)) {
    imgKey = 'velar';
    title = 'Âm cuống lưỡi (' + c + '): Gốc lưỡi nâng chạm vòm ngạc mềm';
  } else if (['j', 'q', 'x'].includes(c)) {
    imgKey = 'palatal';
    title = 'Âm mặt lưỡi (' + c + '): Mặt lưỡi áp phẳng vòm ngạc cứng';
  } else if (['z', 'c', 's'].includes(c)) {
    imgKey = 'dental';
    title = 'Âm đầu lưỡi trước (' + c + '): Lưỡi thẳng áp sau răng trên';
  } else if (['zh', 'ch', 'sh', 'r'].includes(c)) {
    imgKey = 'retroflex';
    title = 'Âm cong lưỡi (' + c + '): Đầu lưỡi uốn cong vút lên ngạc cứng';
  }
  // 2. VẬN MẪU (Finals)
  else if (s === 'vanmau' || ['a','o','e','i','u','ü','ai','ei','ao','ou','an','en','ang','eng','ong'].some(v => c.includes(v))) {
    if (c === 'a') { imgKey = 'bilabial'; title = 'Âm "a": Miệng mở to rộng, lưỡi hạ thấp'; }
    else if (c === 'o') { imgKey = 'velar'; title = 'Âm "o": Môi tròn nhô ra, cuống lưỡi hơi nhô'; }
    else if (c === 'e') { imgKey = 'velar'; title = 'Âm "e": Môi giẹp dẹt nhẹ, cuống lưỡi nâng'; }
    else if (c === 'i') { imgKey = 'palatal'; title = 'Âm "i": Môi dẹp rộng, mặt lưỡi sát ngạc cứng'; }
    else if (c === 'u') { imgKey = 'velar'; title = 'Âm "u": Môi chúm tròn nhô ra, cuống lưỡi cao'; }
    else if (c.includes('ü')) { imgKey = 'palatal'; title = 'Âm "' + c + '": Chúm tròn môi + Lưỡi vị trí âm "i"'; }
    else { imgKey = 'palatal'; title = 'Vận mẫu kép "' + c + '": Khẩu hình trượt chuyển tiếp mượt'; }
  }
  // 3. THANH ĐIỆU (Tones)
  else if (s === 'thanhdieu' || ['1','2','3','4'].some(t => c.includes(t))) {
    if (c.includes('1')) { imgKey = 'bilabial'; title = 'Thanh 1 (55): Âm vực cao, kéo dài bằng phẳng'; }
    else if (c.includes('2')) { imgKey = 'alveolar'; title = 'Thanh 2 (35): Giọng vút lên cao từ trung bình'; }
    else if (c.includes('3')) { imgKey = 'retroflex'; title = 'Thanh 3 (214): Giảm sâu xuống thấp rồi vút lên'; }
    else if (c.includes('4')) { imgKey = 'velar'; title = 'Thanh 4 (51): Rơi xuống nhanh & dứt khoát'; }
    else { imgKey = 'dental'; title = 'Thanh nhẹ: Đọc nhẹ, ngắn & tự nhiên'; }
  }

  const imgSrc = MOUTH_IMAGES[imgKey] || MOUTH_IMAGES.bilabial;

  return `
    <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:4px;">
      <img src="${imgSrc}" alt="${title}" style="width:100%; max-height:140px; border-radius:12px; object-fit:cover; box-shadow:0 6px 18px rgba(0,0,0,0.6); border:2px solid rgba(56,189,248,0.4);" />
      <span style="font-size:0.75rem; color:#38bdf8; font-weight:800; margin-top:6px; text-align:center;">${title}</span>
    </div>
  `;
}
